/**
 * 水滴 —— 🐾 图标上的活动指示器（2026-10-14 三轮定稿）。
 *
 * 本文件是**纯逻辑 + 纯绘制**：不碰 React、不碰 DOM、不读全局时钟。
 * 状态在 `DropletState` 对象里（组件实例各持一份），`advance()` 只依赖
 * `(state, dt, act)` ⟹ 可以在 Node 里完整重演（见 `tests/droplet.spec.ts`），
 * 也可以被页面按 60fps 驱动。**同一份代码**服务真实 UI 与测试——
 * 不做「测试用一份、跑起来用另一份」。
 *
 * ── 三类动作 = 工程切面 ──────────────────────────────
 * 与 `../mbsf-activity.ts` 头注同源（那里是 host 半的分类，这里是它的视觉）：
 *   · 读（读取内容）= 展开成内容 ⟹ 顺时针绕行
 *   · 写（nominate / forget）    = `D` 区分——内容**落成**坐标 ⟹ 逆时针绕行
 *   · 压（压缩）         = 多条合并成一个 ⟹ 停住、交替变扁
 * 注意「压」没有单独动作，本质仍是归并（同一话题的多条消息 → 合并）
 * ⟹ 三类是两个方向的切面，不是一个三分法。
 *
 * ── 形态要点（2026-10-14 一帆逐条定，三轮）───────────────────────────
 *   · 球在 logo **外面**绕（`ORB_R > LOGO_R`）——不挡品牌图
 *   · 尾巴拖在**行进反方向**；跨角随「已进行多久」生长（长调用看得见时间）
 *   · **起步即有基础尾**：0.25s 内长到 `ARC_MIN`，不做「光球干绕」
 *   · 空档**边动态边淡**：继续按上一动作的方向走，尾跨角**冻结**（尾形不塌）
 *   · 文字**快起慢落**：亮 0.10s / 暗 0.30s（亮是「球来了」要灵敏，暗是余晖要缓）
 *
 * ── 幅度硬约束（`tests/droplet.spec.ts` 逐条钉住）────────────────────
 *   · 球全程在 logo 外（读/写最坏 14.60px > 13px；压最坏 13.935px > 13px）
 *   · 球与尾都不出 canvas（读/写 18.40px、压 19.065px ≤ 20px）
 *   · 三类动作的相位/方向语义与 host 侧 `MBSF_TOOLS` 一致
 *
 * ── 为什么 canvas 要 40px 而按钮只有 26px ────────────────────────────
 * 轨道半径 16.5 + 球半径 1.9 = 18.4px（压时 19.065px）⟹ 直径 ~38px。
 * canvas 取 40px 居中盖在按钮上（`left/top = (26 − 40)/2 = −7px`）。
 * ⟹ **祖先链上任何 `overflow: hidden` 都会切掉球**——`MbsfFloatingPanel`
 * 的 `.seat` 到 composer 卡片实测无裁剪（2026-10-14 查证），
 * 但这是**布局契约**：改 composer 样式的人需要知道这里有个溢出 7px 的画布。
 */
/** 球心轨道半径（26px 制）——球整体在 logo 外。 */
export const BTN = 26;
/** logo（= 按钮）半径。 */
export const LOGO_R = BTN / 2;
/** 球外缘与 logo 边缘的净空——「不挡 logo」的量化保证。 */
export const CLEAR = 1.6;
/** 球半径。 */
export const DOT = 1.9;
/** 球心轨道半径 = 13 + 1.6 + 1.9 = 16.5px。 */
export const ORB_R = LOGO_R + CLEAR + DOT;
/** canvas 边长（≥ 2×(ORB_R + DOT·K_SQ) = 38.13 ⟹ 取 40）。 */
export const CV = 40;
/** 尾巴跨角上限（度）——过 180° 就绕成甜甜圈。 */
export const ARC_MAX = 150;
/** 起步尾角（度）——「一动就有尾巴」，不许光球干绕。 */
export const ARC_MIN = 26;
/** 尾宽剖面指数：1 = 直线尖锥（水滴）。 */
export const TAIL_P = 0.9;
/** 尾尖宽度 / 球半径。 */
export const TIP_W = 0.05;
/** 整条水滴的不透明度。 */
export const HEAD_A = 0.88;
/** 渐淡时尾尖的残余不透明度。 */
export const TIP_A = 0.06;
/**
 * 水滴墨色（亮色主题）——近黑的深灰。
 *
 * ── 为什么现在要分亮/暗两套（2026-10-14 三轮·一帆）──────────────────
 * 原先写死一套，理由是「logo 是白底黑图的固定 JPEG，不随主题变」。
 * 但一轮反馈指出：**深色模式下 logo 自己就该反色**（否则白底圆片糊在
 * 深色聊天窗上）。logo 一旦反色，叠在它上面的水滴也必须跟着反——
 * 「覆盖层的前景由被覆盖物决定」这条原则没变，变的是**被覆盖物现在随主题**。
 * ⟹ 墨色成为主题的函数：亮色用深墨，暗色用浅墨。
 */
export const INK_LIGHT = '24,24,27';
/** 水滴墨色（暗色主题）——与 `--dsw-alias-label-primary`（暗色 = 近白）同域。 */
export const INK_DARK = '249,250,251';
/**
 * 压缩形变系数——上下 ⇄ 左右交替变扁，面积守恒（`sx·sy ≡ 1`）。
 *
 * ── 上限是算出来的，不是调出来的（2026-10-14 三轮）───────────────────
 * 球心轨道半径 `ORB_R = 16.5`，而三个方向的「可用余量」**恰好都是 3.5px**：
 *
 * ```
 *   logo 边缘     13.0   ⟹ 16.5 − 13.0 = 3.5   （球内缘不压 logo）
 *   canvas 边缘   20.0   ⟹ 20.0 − 16.5 = 3.5   （球外缘不被裁）
 *   右侧文字      20.0   ⟹ 20.0 − 16.5 = 3.5   （球外缘不压文字，= LOGO_R + gap 7）
 * ```
 *
 * 半轴最大 = `DOT · K` ⟹ `1.9K ≤ 3.5` ⟹ **K ≤ 1.842**（三个约束同时到期）。
 * 取 **1.7**：比原 1.35 明显更扁（+26%），仍留 0.27px 净空。
 * `tests/droplet.spec.ts` 钉住 `K_SQ < K_SQ_MAX`——再往上调会先红。
 */
export const K_SQ = 1.7;
/** 压缩形变系数上限（`(ORB_R − LOGO_R) / DOT`，三约束同值）。 */
export const K_SQ_MAX = (ORB_R - LOGO_R) / DOT;
/** 压缩形变周期（ms）——与轨道周期不同，避免两通道锁相。 */
export const SQ_MS = 1400;
/** 淡入时长（秒）。 */
export const FADE_IN = 0.25;
/**
 * 淡出时长的**下限**（秒）——「边动态边淡」的最短观感长度。
 *
 * ⚠ 三轮起余韵时长**不再是常数**：球要从当前位置走到**下一个顶部**，
 * 走多久就淡多久（`fadeOut = max(FADE_OUT_MIN, 距离 × SEC_PER_TURN)`）
 * ⟹ 走到顶部与淡到 0 **同时发生**（终点必然在正上方）。
 * 距离很短时用这个下限兜底，避免「一闪就没」。
 */
export const FADE_OUT_MIN = 0.45;
/** 尾长生长起点（秒）——T₀ 之前只有基础尾。 */
export const T0 = 3.5;
/** 基础尾出生时长（秒）——「一动就有尾巴」。 */
export const T_BORN = 0.25;
/** 尾长饱和点（秒）——到 ARC_MAX。 */
export const TMAX = 30;
/** 文字亮度上升时间常数（秒）——快。 */
export const GLOW_ATTACK = 0.1;
/** 文字亮度下降时间常数（秒）——比上升慢（一帆：「暗的时候可以比明的时候稍慢些」）。 */
export const GLOW_RELEASE = 0.3;
/** 亮度曲线指数——三次方是**窗口宽度**的选择（见 `glowAt`）。 */
export const GLOW_P = 3;
/** 一圈秒数——对齐 DSH 既有指示器节奏（1.2s）。 */
export const SEC_PER_TURN = 1.2;
/**
 * 顶部相位（圈）——**起点 / 终点 / 压缩点**。
 *
 * `orbitAt(0.75) = (0, −1)` = 屏幕正上方（`orbitAt(0.25)` 是正下方）。
 *
 * ── 为什么锚在顶部（2026-10-14 三轮·一帆）────────────────────────────
 * 「起点和终点和压缩都在 logo 正上方」——三个理由：
 *   ① **可预期**：每次动作都从同一个地方出发、回到同一个地方，
 *      不积累漂移（否则看久了会觉得球"跑偏了"）。
 *   ② **压缩有地方变扁**：顶部两侧是空的（球心 (0,−16.5)，左右各有
 *      ~16px 余量），而右侧紧邻动作文字（gap 7px）——在顶部变扁最自由。
 *   ③ **一次动作 = 整数圈**：球从顶部出发，结束时继续走到**下一个顶部**
 *      才停，走过的总弧长恰好是整数圈 ⟹ 「起点终点都在正上方」自动成立。
 *
 * ⚠ 与设计稿 §3.7(1)「位置是连续累加的弧长」的关系：**相位仍然连续**
 * （换方向只翻符号、永不瞬移），只是**停靠点**锚在顶部。两者不冲突——
 * 「连续」说的是过程中不跳，「锚顶」说的是停在哪。
 */
export const TOP_PHASE = 0.75;
/** 到达顶部的容差（圈）——小于它即视为已到达（浮点累积误差）。 */
const TOP_EPS = 1e-6;
/**
 * 最短显示时长（毫秒）——**出现即保证看得见**。
 *
 * 缓存命中的调用只有 ~50ms：若按真实时长渲染，水滴只长到基础尾的 1/5
 * 就被撤掉，视觉上是一次抖动（不是「动过」）。故活动到来后**至少**保持
 * 这么久才允许进入淡出——与旧的 `ACTIVITY_CYCLE_MS`（1200ms，保证播完
 * 一整个环）同一意图，只是水滴的时间尺度更短（基础尾 250ms + 余韵 450ms）。
 */
export const MIN_ACT_MS = 400;
/**
 * 压缩动作的最短显示时长（毫秒）——**必须够播完一个完整形变周期**。
 *
 * ── 为什么压缩要单独一条（2026-10-14 四轮·一帆：「压缩闪太快」）────────
 * `MIN_ACT_MS`（400ms）是照**读/写**的时间尺度定的：基础尾 250ms + 一点
 * 余韵就够看。但压缩的节奏由 `SQ_MS`（1400ms）主导——球要**慢慢变扁再
 * 鼓回来**，这是一个完整周期。400ms 连三分之一周期都不到就被撤掉 ⟹
 * 压缩永远是「闪一下就没了」，形变根本来不及成形。
 *
 * 真实事务时长也印证：压缩的 `start→end` 实测只有 70~300ms，远短于
 * 1400ms 的形变周期 ⟹ 不加这条保底，压缩动作**必然**被腰斩。
 *
 * ⚠ 不把 `MIN_ACT_MS` 全局提到 1400：读/写会被一起拖长，缓存命中的
 * ~50ms 调用要卡满 1.4 秒，手感发黏。**只给压缩加保底。**
 */
export const MIN_COMPACT_MS = SQ_MS;
/**
 * 按动作取「最短显示时长」——形态不同，该看的时长也不同。
 *
 * @param act - 动作形态（`idle` 无意义——调用方不应在空闲时问）。
 * @returns 该动作至少应显示的毫秒数。
 */
export function minActMs(act) {
    return act === 'compact' ? MIN_COMPACT_MS : MIN_ACT_MS;
}
/** 方向：读顺时针（屏幕坐标 y 向下 ⟹ 角度递增 = 视觉顺时针）/ 写逆时针 / 压不动。 */
export const DIRS = {
    read: +1, write: -1, compact: 0, idle: 0,
};
/**
 * 从 `u` 沿 **+1** 方向走，遇到的第一个顶部相位（≥ u，含自身）。
 *
 * 「顶部」= `TOP_PHASE + 整数`（相位每加 1 圈回到同一点）。
 * `TOP_EPS` 让「已经在顶部」判定不受浮点累积影响（否则会白走一整圈）。
 */
function topAtOrAfter(u) {
    return TOP_PHASE + Math.ceil((u - TOP_PHASE) - TOP_EPS);
}
/** 从 `u` 沿 **−1** 方向走，遇到的第一个顶部相位（≤ u，含自身）。 */
function topAtOrBefore(u) {
    return TOP_PHASE - Math.ceil((TOP_PHASE - u) - TOP_EPS);
}
/** 是否已在顶部（含浮点容差）。 */
export function atTop(u) {
    const d = (((u - TOP_PHASE) % 1) + 1) % 1;
    return d < TOP_EPS || d > 1 - TOP_EPS;
}
/**
 * 余韵是否已经走完（可以卸载画布了）。
 *
 * ── 为什么需要这个判断（2026-10-14 四轮·一次真实故障）────────────────
 * 组件原先靠 `act` 变 `'idle'` 来调 `endActivity`，但 `act` 是**形态**
 * （`ACTIVITY_FACE` 只产出 read / write / compact），`'idle'` 永远不来；
 * 而活动消失时组件直接**整个卸载**，rAF 随之停 ⟹ `endActivity` 一次都
 * 没被调用过 ⟹ 余韵、锚顶、边淡边走**全部落空**（球只会硬生生消失）。
 *
 * 修法：水滴**自管生命周期**——活动消失时传 `'idle'` 进来（不卸载），
 * 由本函数判断「余韵跑完了」，跑完才让组件摘掉画布。
 *
 * ⚠ 判定条件必须是 `vis` 而非 `elapsed`：余韵期 `active === false`，
 * 但球还在走、还在淡，此时摘掉画布 = 半路掐断。
 *
 * @param s - 状态。
 * @returns 是否已完全静止（可卸载）。
 */
export function settled(s) {
    return !s.active && s.vis <= 0;
}
/**
 * 从 `u` 到顶部**最短**该走哪个方向（+1 / −1）；已在顶部 ⟹ 0。
 *
 * 压缩自己没有方向（`DIRS.compact = 0`），但「压缩要发生在顶部」——
 * 若球不在顶部（读/写途中切到压缩），就走最短的那半圈上去。
 */
export function shortestToTop(u) {
    const d = (((u - TOP_PHASE) % 1) + 1) % 1; // u 相对顶部的「顺时针偏移」，[0,1)
    if (d < TOP_EPS || d > 1 - TOP_EPS)
        return 0;
    return d <= 0.5 ? -1 : +1; // 顺时针偏移 < 半圈 ⟹ 逆时针回去更近
}
/** 新状态（未启动）。 */
export function createState() {
    return {
        u: TOP_PHASE, vis: 0, active: false, act: 'idle', dir: 0, arc: 0, frozenArc: 0,
        elapsed: 0, clock: 0, glow: 0,
        fadeOut: FADE_OUT_MIN, fadeFrom: TOP_PHASE, fadeTurns: 0, fadeElapsed: 0, fadeVis0: 0,
    };
}
/**
 * 尾长映射（2026-10-14 一帆「一开始动就应该有一点基础尾巴」）。
 *
 * ```
 * 跨角(T) = ARC_MAX · born(T) · [ ARC_MIN/ARC_MAX + (1 − ARC_MIN/ARC_MAX)·grow(T) ]
 *   born(T) = min(T / T_BORN, 1)                     —— 出生段：0 → ARC_MIN
 *   grow(T) = √(clamp((T − T₀)/(Tmax − T₀), 0, 1))   —— 生长段：T₀ 之后往 ARC_MAX
 * ```
 *
 * 两段的用意：`T₀` 之前恒为 0 的旧版是**光球干绕**——「读 = 展开」唯一的
 * 时间箭头，正好在最该看见的开头缺席。`T ≥ T₀` 时 `born ≡ 1` ⟹ 退化成
 * 原曲线，老读数不变。
 *
 * @param T - 已进行秒数。
 * @returns 归一化尾长 0..1（T ≤ 0 取 0）。
 */
export function tailLen(T) {
    if (T <= 0)
        return 0;
    const born = Math.min(T / T_BORN, 1);
    const grow = Math.sqrt(Math.min(Math.max((T - T0) / (TMAX - T0), 0), 1));
    const base = ARC_MIN / ARC_MAX;
    return born * (base + (1 - base) * grow);
}
/**
 * 尾长 → 实际跨角（度）。
 * @param T - 已进行秒数。
 * @returns 跨角（度）。
 */
export function tailArc(T) {
    return ARC_MAX * tailLen(T);
}
/**
 * 球扫过文字那一侧时，文字亮多少：0 = 常态，1 = 最亮。
 *
 * 度量用球心的**朝向文字的分量** `cos(2πu)`：文字在按钮右侧 ⟹ `u=0`
 * （球在最右）最近、`u=0.5` 最远。取三次方是**窗口宽度**的选择（不是美术
 * 选择）：`glow ≥ 0.5` 的窗口 `|θ| ≤ 37°`，1.2s/圈下亮约 0.25s——
 * 短到像「擦过」，长到眼睛跟得上（实测占一圈 20.8%）。
 *
 * @param u - 球相位（圈）。
 * @returns 亮度目标 0..1。
 */
export function glowAt(u) {
    const toward = Math.max(0, Math.cos(u * 2 * Math.PI));
    return Math.pow(toward, GLOW_P);
}
/**
 * 平面圆周上的位置（单位圆）。
 * @param u - 相位（圈，可为负）。
 * @returns 单位圆上的点。
 */
export function orbitAt(u) {
    const th = u * 2 * Math.PI;
    return { x: Math.cos(th), y: Math.sin(th) };
}
/**
 * 动作开始（活动投影从「无」变「有」，或换成另一个动作）。
 *
 * ⚠ **必须由调用方在活动变化时调用**——不能靠 `advance()` 内部比较
 * `act !== s.act` 来推断：同一类动作连续来两次（read → 空档 → read）时
 * 后者会让 `elapsed` 不归零，尾巴就不重长（第二次读没有「出生段」）。
 * 把生命周期做成显式调用，这个坑在类型层面就消失了。
 *
 * @param s - 状态。
 * @param act - 新动作（`idle` 无意义——结束请用 `endActivity`）。
 */
export function beginActivity(s, act) {
    if (act === 'idle')
        return;
    s.active = true;
    s.act = act;
    // 压缩自己没有方向（`DIRS.compact = 0`）——但压缩要发生在**顶部**：
    // 不在顶部（读/写途中切过来）就先走最短的那半圈上去，到了再停住变扁。
    s.dir = act === 'compact' ? shortestToTop(s.u) : DIRS[act];
    s.elapsed = 0; // 尾巴从基础尾重新长
    s.arc = null; // 不再冻结——按 elapsed 实时算
    s.frozenArc = 0;
}
/**
 * 动作结束（活动投影回到「无」）——冻结尾跨角，进入余韵。
 *
 * 冻结的意义：尾形**不塌回光球**。淡出期继续按上一动作的方向走，
 * 但尾巴长度停在动作末帧的值（「余韵留在运动里，不是停在静止里」）。
 *
 * @param s - 状态。
 */
export function endActivity(s) {
    if (!s.active)
        return;
    s.active = false;
    s.arc = s.frozenArc; // 尾巴**冻结长度**（不缩回光球）
    // ── 余韵：沿当前方向走到**下一个顶部**，边走边淡，到顶与淡完同时发生
    //
    // 「起点/终点都在正上方」的实现点：终点取「下一个顶部相位」，而顶部
    // 是 `TOP_PHASE + 整数` ⟹ 起点在顶、终点在顶，总行程必为**整数圈**
    //（这正是「每次至少走完一圈」的来源——它是锚顶的推论，不是额外规定）。
    //
    // 尾巴全程带着**冻结的长度**一起绕行，到顶部整条水滴一起消失——
    // 长度是「读了多少」的进度，缩回去等于进度倒退，所以不缩。
    // 方向来源：读/写用当前方向；压缩若还在上顶途中（dir ≠ 0）沿它继续，
    // 已停在顶部（dir = 0）⟹ 原地淡出（fadeTurns = 0）。
    const dir = s.dir !== 0 ? s.dir : 0;
    const target = dir > 0 ? topAtOrAfter(s.u)
        : dir < 0 ? topAtOrBefore(s.u)
            : s.u;
    s.fadeFrom = s.u;
    s.fadeTurns = target - s.u;
    s.fadeElapsed = 0;
    s.fadeVis0 = s.vis;
    s.fadeOut = Math.max(FADE_OUT_MIN, Math.abs(s.fadeTurns) * SEC_PER_TURN);
}
/**
 * 推进一帧。
 *
 * ⚠ **顺序是硬约束**（二轮踩过的坑，`tests/droplet.spec.ts` 钉住）：
 * 先算**本帧** `vis`，再用更新后的值决定「走不走」。旧写法（先判 `vis > 0`
 * 再更新）会让淡到 0 的那一帧多走一步——看不见的位移。
 *
 * @param s - 状态（**原地修改**——每帧调用，不分配对象）。
 * @param dt - 本帧时长（秒）。
 */
export function advance(s, dt) {
    s.clock += dt;
    if (s.active) {
        s.elapsed += dt;
        s.frozenArc = s.act === 'read' || s.act === 'write' ? tailArc(s.elapsed) : 0;
        // 可见度：淡入（与「走不走」无关——先算再判，见下方纪律）
        s.vis = Math.min(1, s.vis + dt / FADE_IN);
        if (s.act === 'compact') {
            // 压缩要发生在顶部：不在顶部就先上去（最短方向），到了就停住变扁
            if (!atTop(s.u)) {
                s.u += (dt * s.dir) / SEC_PER_TURN;
                // ⚠ 用 atTop 判定「到了」，不要用 floor/ceil 比较：球**恰好落在**
                //   顶部那一帧整数部分没变（0.7501 → 0.7500），floor 比较会漏判
                //   ⟹ dir 不归零、球继续往前跑（tests/droplet.spec.ts 抓到）。
                if (atTop(s.u)) {
                    // 精确落到顶部（消掉这一帧的越界残量）
                    s.u = TOP_PHASE + Math.round(s.u - TOP_PHASE);
                    s.dir = 0; // 到位 ⟹ 停住（压缩的「原地」）
                }
            }
        }
        else if (s.dir !== 0) {
            s.u += (dt * s.dir) / SEC_PER_TURN;
        }
    }
    else if (s.vis > 0) {
        // ── 余韵：按**进度**插值（不是按速率），走到顶部与淡到 0 同时发生
        //
        // 用进度而不是「每帧减 dt/fadeOut」再单独推进相位：后者两个累积量各自
        // 漂移，终点会差一点点（到不了精确的顶部）。插值 ⟹ p = 1 时 u 恰好在顶。
        s.fadeElapsed += dt;
        const p = Math.min(1, s.fadeElapsed / s.fadeOut);
        s.u = s.fadeFrom + s.fadeTurns * p;
        s.vis = s.fadeVis0 * (1 - p);
        if (p >= 1) {
            s.u = s.fadeFrom + s.fadeTurns; // 精确落在顶部（消掉浮点残差）
            s.vis = 0;
        }
    }
    // 文字亮度：目标由**本帧更新后的** u 与 vis 决定，跟随速度按方向取不同时间常数
    const glowTarget = s.vis > 0 ? glowAt(s.u) : 0;
    const glowRate = dt / (glowTarget > s.glow ? GLOW_ATTACK : GLOW_RELEASE);
    s.glow = glowTarget > s.glow
        ? Math.min(glowTarget, s.glow + glowRate)
        : Math.max(glowTarget, s.glow - glowRate);
}
/** 画球（可带形变）。`sx`/`sy` = 横/竖半轴相对 DOT 的倍率。 */
function drawBall(ctx, c, R, u, alpha, sx, sy, ink) {
    if (alpha <= 0.004)
        return;
    const p = orbitAt(u);
    ctx.beginPath();
    ctx.ellipse(c + p.x * R, c + p.y * R, DOT * sx, DOT * sy, 0, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(${ink},${(HEAD_A * alpha).toFixed(3)})`;
    ctx.fill();
}
/**
 * 画水滴 = 球 ∪ 尾巴。
 *
 * **单条闭合路径、单次 fill**——分两次画会让重叠处 alpha 叠深，接缝处留
 * 一条黑边。`dir` = +1 顺时针 / −1 逆时针：尾巴永远拖在行进反方向。
 */
function drawDrop(ctx, c, R, uHead, arcTail, dir, alpha, ink) {
    if (alpha <= 0.004)
        return;
    const steps = Math.max(24, Math.round(arcTail / 1.5));
    const span = (arcTail / 360) * 2 * Math.PI;
    const a0 = uHead * 2 * Math.PI;
    const aTip = a0 - dir * span;
    const OUT = [];
    const IN = [];
    let tipCx = 0, tipCy = 0, tipHw = 0;
    for (let i = 0; i <= steps; i++) {
        const t = i / steps; // 0 = 尾尖(后), 1 = 贴球(前)
        const ang = a0 - dir * span * (1 - t);
        const cx = c + Math.cos(ang) * R;
        const cy = c + Math.sin(ang) * R;
        const hw = DOT * (TIP_W + (1 - TIP_W) * Math.pow(t, TAIL_P)); // 尾尖细丝 → 贴球处 = 球半径
        const nx = Math.cos(ang);
        const ny = Math.sin(ang);
        OUT.push([cx + nx * hw, cy + ny * hw]);
        IN.push([cx - nx * hw, cy - ny * hw]);
        if (i === 0) {
            tipCx = cx;
            tipCy = cy;
            tipHw = hw;
        }
    }
    const hx = c + Math.cos(a0) * R;
    const hy = c + Math.sin(a0) * R;
    ctx.beginPath();
    const out0 = OUT[0];
    ctx.moveTo(out0[0], out0[1]);
    for (let i = 1; i <= steps; i++) {
        const p = OUT[i];
        ctx.lineTo(p[0], p[1]); // 外缘：尾尖 → 球
    }
    // 球的外半圆：朝行进方向那一侧（dir=+1 走 a0→a0+π；dir=−1 走 a0→a0−π）
    ctx.arc(hx, hy, DOT, a0, a0 + dir * Math.PI, dir < 0);
    for (let i = steps; i >= 0; i--) {
        const p = IN[i];
        ctx.lineTo(p[0], p[1]); // 内缘：球 → 尾尖
    }
    // 尾尖圆头：朝行进反方向鼓出
    ctx.arc(tipCx, tipCy, tipHw, aTip, aTip - dir * Math.PI, dir > 0);
    ctx.closePath();
    // 尾尖渐淡：从尾尖的残余透明度渐变到球头的不透明度
    const g = ctx.createLinearGradient(tipCx, tipCy, hx, hy);
    g.addColorStop(0, `rgba(${ink},${(HEAD_A * TIP_A * alpha).toFixed(3)})`);
    g.addColorStop(1, `rgba(${ink},${(HEAD_A * alpha).toFixed(3)})`);
    ctx.fillStyle = g;
    ctx.fill();
}
/**
 * 画一帧。
 *
 * @param ctx - 2D 上下文。
 * @param size - canvas 逻辑边长（= `CV`）。
 * @param eff - backing store 倍率（devicePixelRatio × 放大倍数）。
 * @param s - 状态。
 */
export function drawFrame(ctx, size, eff, s, ink = INK_LIGHT) {
    ctx.setTransform(eff, 0, 0, eff, 0, 0);
    ctx.clearRect(0, 0, size, size);
    if (s.vis <= 0.004)
        return;
    const c = size / 2;
    const R = ORB_R;
    if (s.act === 'compact') {
        // 原地上下 ⇄ 左右交替变扁（面积守恒：sx·sy ≡ 1）
        //   e = +1 ⟹ 横长竖扁；e = −1 ⟹ 横扁竖长（一个周期里两种都走一遍）
        // ⚠ 只在**顶部**变扁：若还在赶往顶部的路上（读/写途中切来），先以球形走，
        //   到位才变形——「停在原地变扁」的「原地」就是顶部。
        if (atTop(s.u)) {
            const e = Math.cos((s.clock / (SQ_MS / 1000)) * 2 * Math.PI);
            drawBall(ctx, c, R, s.u, s.vis, Math.pow(K_SQ, e), Math.pow(K_SQ, -e), ink);
        }
        else {
            drawBall(ctx, c, R, s.u, s.vis, 1, 1, ink);
        }
        return;
    }
    // 跨角：有动作 ⟹ 按已进行时长算；渐淡期 ⟹ 用动作结束瞬间冻结的值（尾形不塌）
    const arcTail = s.arc ?? ((s.act === 'read' || s.act === 'write') ? tailArc(s.elapsed) : 0);
    if (arcTail > 2)
        drawDrop(ctx, c, R, s.u, arcTail, s.dir, s.vis, ink);
    else
        drawBall(ctx, c, R, s.u, s.vis, 1, 1, ink);
}
/**
 * 绘制一帧静态水滴（`prefers-reduced-motion` 用）——不跑动画，只留形态。
 *
 * 尊重系统「减弱动态效果」：信息（正在做事）不丢，只是不闪。
 *
 * @param ctx - 2D 上下文。
 * @param size - canvas 逻辑边长。
 * @param eff - backing store 倍率。
 * @param act - 当前动作。
 */
export function drawStaticFrame(ctx, size, eff, act, ink = INK_LIGHT) {
    const s = createState();
    s.active = true;
    s.act = act === 'idle' ? 'read' : act;
    s.dir = DIRS[s.act];
    s.vis = 1;
    s.u = TOP_PHASE; // 锚在顶部（与动态的停靠点一致）
    s.elapsed = T0; // 已过生长起点 ⟹ 有可见的尾巴
    s.clock = 0;
    drawFrame(ctx, size, eff, s, ink);
}
