/**
 * 未必记忆设置面（浏览器半）——装配一条顶层设置页贡献：
 *
 * 「设置 → 未必记忆」顶层页：上半功能开关（记忆浮现 / γ 自动压缩，staged +
 * save），下半只读六块统计（Remote `mbsfStatus`）。
 *
 * Remote 契约手写于 mbsf-remote.ts（engine 是独立仓库，无法在 client 侧
 * import 其生成物；host 端 status-gateway 的 `@Remote('snapshot')` 与这里
 * 的 descriptor 是同一契约的两个半）。
 */
import mbsfStatusRemote from "./mbsf-remote.js";
import { ESHEEP_NS, MbsfCardController } from "./mbsf-card-controller.js";
import { watchNavIcon } from "./brand-nav-icon.js";
import { bindSettingsScope } from "./settings-adapter.js";
import { decodeMbsfSettings } from "./settings-decode.js";
import { MbsfSettingsSection } from "./MbsfSettingsSection.js";
import { en, zh } from "./locales.js";
import { INTL_DICTIONARIES } from "./locales-intl.js";
import { SessionSwitchesController, } from "./SessionSwitches.js";
import { MbsfFloatingPanel } from "./MbsfFloatingPanel.js";
/** Dictionary namespace owned by this plugin. */
export const NS = 'settings.electronicSheep';
/** 0.1.7 的配置命名空间 = 引擎状态网关在 profile 里的 **loader entry id**
 *  （`- id: mbsf-status`）。0.1.7 的 settings 文档按 entry id 索引 namespace
 *  （`describe()` 里 `ns: entry.options.id`），而 schema 来自该 entry 的
 *  `static Config`（`MbsfStatusGateway.Config`）。
 *
 *  为什么不是 'mbsf'：那是 **0.1.5** 的 namespace——引擎在 0.1.5 下经
 *  `settings.register('mbsf', …)` 自报的名字，与宿主装配的 entry id 无关。
 *  两版用两个名字是结构使然（0.1.5 由插件自报、0.1.7 由宿主装配决定），
 *  所以适配层收 `{ legacy, modern }` 两个值。
 *
 *  ⚠️ 必须与 profile 里 `mbsf-status` 那一行的 id 保持一致；改装配 id 要
 *  同步改这里（否则卡片退回 `status: 'unavailable'`）。 */
export const MBSF_STATUS_ENTRY_ID = 'mbsf-status';
/**
 * Services required by the Settings registration and the mounted Remote.
 *
 * ⚠ `settingsScope` **刻意不在这里**（2026-09-27 小爪）。它是 0.1.5 的客户端
 * 设置服务；app 版（DSH 0.1.7-rc.2）没有它。Cordis 的 `Fiber._refresh()` 逐
 * 个检查 `Object.keys(this.inject)`，缺一个就永远停在 `INACTIVE` —— 这正是
 * 2026-09-26 app 启动日志里那条
 * `@deepseek-ai/dsh-client-ui-settings-mbsf: pending (waiting for service: settingsScope)`
 * 的根因，整条插件（含状态页、🐾 浮窗）因此从未激活。
 *
 * 改成运行时用 `ctx.get` 探测（无 inject 守卫，取不到即 undefined），
 * 由 settings-adapter 决定走 0.1.5 的 settingsScope 还是 0.1.7 的 configForms。
 */
export const inject = ['slots', 'locale', 'remote'];
/**
 * Mount the MBSF Remote, then contribute the top-level settings
 * section (switches + status).
 * @param ctx - the browser plugin context.
 * @returns disposer after the Remote contribution and the section entry.
 */
export async function apply(ctx) {
    // 先 mount（apply 的 fiber 拥有 mbsfStatus 服务），再注册 slot——
    // slot 的 injected 快照函数在渲染期才调用，届时 remote 已就绪。
    //
    // 注意：不能把 'remote.mbsfStatus' 加入 inject 声明——本插件自 mount
    // 自用，fiber 创建期服务尚未注册，_checkImpl 会失败导致 fiber 永不激活
    // （死锁）。同样也不能经 ctx.remote.mbsfStatus 属性访问：Cordis 的
    // handler.get 沿调用者 fiber 链找提供者，而服务注册在 mount 的 namespace
    // fiber 的 store 里，不在调用者父链上，会抛 without inject。正确姿势是
    // $mount 完成后用 ctx.get 直读共享 store（无 inject 守卫）。
    const unmount = await ctx.remote.$mount(mbsfStatusRemote);
    const mbsfStatus = ctx.get('remote.mbsfStatus');
    // ── 设置作用域：双版本适配（2026-09-27）────────────────────────────────
    // 0.1.5：`ctx.settingsScope.bind({ namespace, decode })`
    // 0.1.7：`ctx.configForms.get(entryId)`（服务名与取用方式都变了）
    // 两者都用 `ctx.get` 取（无 inject 守卫），由适配层挑一个；都取不到时
    // scope === undefined —— 卡片渲染为不可用，但状态页与浮窗照常工作。
    // ⚠️ 新增 `MbsfRuntimeConfig` 字段时：改 `runtime-config.ts` + `MbsfSettings`
    // + `settings-decode.ts` 的字段表，**三处**。漏第三处的症状是「开关保存后
    // 弹回」且极难查——写路径全对（`scope.set` 落盘成功、`config.json` 里值是对
    // 的），只有读回这层把值丢了 → 渲染回落默认值。2026-09-27 实测事故：
    // `autoReclaimEnabled` 落盘为 true 而 UI 恒显示「关闭」（连同
    // `sessionStreamKeepCount` / `autoReclaimThresholdPct` 共 3 个字段漏解码）。
    //
    // 该事故后解码表已提出到 `settings-decode.ts`，并接上构建期差集校验
    // （`scripts/check-settings-decode.mjs`）——**漏第三处 = 构建失败**，
    // 不再靠人肉发现。此处只是引用。
    const decodeSettings = decodeMbsfSettings;
    const scope = bindSettingsScope({
        settingsScope: ctx.get('settingsScope'),
        // 0.1.7 的 namespace = loader entry id，**不是** 0.1.5 的 'mbsf'：
        // 配置 schema 挂在宿主层 `mbsf-status` 条目的 `static Config` 上，
        // settings 文档的 ns 就是该条目的 id。
        configForms: ctx.get('configForms'),
    }, { legacy: ESHEEP_NS, modern: MBSF_STATUS_ENTRY_ID }, decodeSettings);
    const card = new MbsfCardController(scope);
    // 绑定一次：渲染器复用同一快照 store（每次注入新建会泄漏订阅）。
    const mbsfCard = card.bind();
    ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'ui-settings-mbsf: dictionaries');
    // 非内置语种（2026-11-07）：DSh 只内置 zh/en，其余语言要么等第三方语言包，
    // 要么自己带——本插件随包提供 8 本完整译稿，用户切到该语言即刻生效，不需要
    // 为了看母语界面去改未必科幻（见 locales-intl.ts 头注）。
    //   · 字典：单语形 register。
    //   · 语言定义：addLanguage——没有定义就不出现在语言列表里；同 id 已被别的
    //     语言包占用时它会抛，这里吞掉（别人的包优先，我们不抢注册权）。
    ctx.effect(() => {
        const disposers = [];
        for (const entry of INTL_DICTIONARIES) {
            try {
                disposers.push(ctx.locale.register(NS, entry.id, entry.dict));
            }
            catch {
                // 同 (ns, locale) 已被占用（重复加载/热重载）→ 跳过
            }
            try {
                disposers.push(ctx.locale.addLanguage({ id: entry.id, label: entry.label, fallback: 'en' }));
            }
            catch {
                // 语言 id 已注册（第三方语言包先到）→ 用别人的定义，仍用我们的字典
            }
        }
        return () => { for (const dispose of disposers)
            dispose(); };
    }, 'ui-settings-mbsf: intl dictionaries');
    const t = ctx.locale.bind(NS);
    // 品牌 logo 跟随界面语言（2026-11-07）：只说「语言是什么、什么时候变」，
    // 选哪张图在组件侧（brand.ts 的 selectBrandLogo）。
    const brandLocale = {
        getId: () => ctx.locale.getSnapshot().active,
        subscribe: (fn) => ctx.locale.subscribe(fn),
    };
    const injected = {
        snapshot: async () => {
            const result = await mbsfStatus.snapshot();
            if (!result.ok) {
                throw new Error(`mbsfStatus.snapshot failed: ${result.error.code}: ${result.error.message}`);
            }
            // 快照到手时把本机堆上限喂给滑块（引擎按物理内存算出——UI 不猜）。
            // 只读副作用：更新的是 controller 的展示上界，不进 settings 文档。
            const maxMb = result.value.heap?.maxMb;
            if (typeof maxMb === 'number')
                card.setHeapMax(maxMb);
            // 实际生效的堆上限（百分比阈值换算 MB 显示用——App 形态下配置值不生效）。
            const limitMb = result.value.heap?.limitMb;
            if (typeof limitMb === 'number')
                card.setHeapLimit(limitMb);
            return result.value;
        },
        toggle: (field) => { card.toggle(field); },
        save: () => { void card.save(); },
        discard: () => { card.discard(); },
        resetField: (field) => { card.resetField(field); },
        setNumber: (field, value) => { card.setNumber(field, value); },
        restartDsh: async () => {
            const result = await mbsfStatus.restart('');
            return result.ok ? result.value : { ok: false, detail: `${result.error.code}: ${result.error.message}` };
        },
        memoryReport: async () => {
            const result = await mbsfStatus.memoryReport();
            if (!result.ok)
                throw new Error(`${result.error.code}: ${result.error.message}`);
            return result.value;
        },
        reclaimMemory: async () => {
            const result = await mbsfStatus.reclaimMemory();
            return result.ok ? result.value : {
                ok: false, reclaimed: 0, before: 0, after: 0, gcMs: 0, clearedEntries: {},
                detail: `${result.error.code}: ${result.error.message}`,
            };
        },
        trimTargets: async () => {
            const result = await mbsfStatus.trimTargets();
            if (!result.ok)
                throw new Error(`${result.error.code}: ${result.error.message}`);
            return result.value;
        },
        setTrimTarget: async (sessionId, selected) => {
            const result = await mbsfStatus.setTrimTarget({ sessionId, selected });
            if (!result.ok)
                throw new Error(`${result.error.code}: ${result.error.message}`);
        },
        trimDelete: async (sessionId) => {
            const result = await mbsfStatus.trimDelete({ sessionId });
            // 失败是**业务结果**（活跃会话不可删等），不是异常：交给界面显示原因。
            if (!result.ok)
                return { ok: false, deleted: [], bytes: 0, detail: `${result.error.code}: ${result.error.message}` };
            return result.value;
        },
        trimDeleted: async () => {
            const result = await mbsfStatus.trimDeleted();
            if (!result.ok)
                throw new Error(`${result.error.code}: ${result.error.message}`);
            return result.value;
        },
        trimRestore: async (sessionId) => {
            const result = await mbsfStatus.trimRestore({ sessionId });
            if (!result.ok)
                return { ok: false, restored: [], detail: `${result.error.code}: ${result.error.message}` };
            return result.value;
        },
        hooks: { mbsfCard },
    };
    // 顶层设置页（与 ui-agent-preset 的 section 注册同构）：侧栏导航出现
    // 「未必记忆」入口，页面内含功能开关与运行状态。
    ctx.slots.inject('settings.section', () => ctx.slots.register({
        name: 'settings.section',
        id: 'mbsf',
        order: 30,
        label: () => t('nav'),
        locale: NS,
        inject: () => injected,
    }, MbsfSettingsSection));
    // 导航图标（2026-11-07 一帆）：宿主 `settings.section` 没有 icon 选项，
    // 未知 id 一律画齿轮——在面板真正挂载后把齿轮换成品牌图形（见
    // brand-nav-icon.ts 头注：为什么是「隐藏 + 插兄弟节点」而不是替换）。
    ctx.effect(() => watchNavIcon(() => t('nav')), 'ui-settings-mbsf: nav icon');
    // ===== 会话级注入开关（2026-09-02 固化——子代理/分叉会话默认继承父会话
    // 设置；🐾 浮窗 = 会话级覆盖的显式落点）=====
    // 控制器/快照按会话缓存（同一会话重复挂载复用 store——每次新建会泄漏
    // 订阅，与 mbsfCard 同教训）；Map 超限清最旧（工程视界，防无界增长）。
    // 会话配置端点与快照同在 mbsfStatus 命名空间（host gateway 只认服务
    // binding 的 namespace，无法另开 sessionConfig），故复用已 mount 的
    // mbsfStatus 句柄即可。
    // 落点说明：官方 ui-conversation 无「选项卡环 trailing」渲染位（插件侧
    // declare 的 slot 名 shell 不 renderSlot，组件永不渲染），故挂官方声明
    // 并渲染的 `conversation.input.left`（工具行左侧常驻小控件 seat）——
    // 零官方源码改动，别人装本插件同样可见。
    const sessionControllers = new Map();
    const sessionStores = new Map();
    const MAX_SESSION_SWITCH_STATES = 200;
    const sessionSwitchesFor = (sessionId) => {
        let controller = sessionControllers.get(sessionId);
        let store = sessionStores.get(sessionId);
        if (controller === undefined) {
            controller = new SessionSwitchesController(mbsfStatus, sessionId);
            // 全局档位（动画 / 文字开关）改动时重新拉取——否则浮窗读的永远是挂载
            // 那一刻的旧值（「设置页关了、浮窗还在动」，2026-10-14 修）。
            controller.watchSettings(scope);
            sessionControllers.set(sessionId, controller);
            if (sessionControllers.size > MAX_SESSION_SWITCH_STATES) {
                // Map 迭代序 = 插入序，删最旧一条即可回收（工程视界，非判定）。
                const oldest = sessionControllers.keys().next().value;
                if (oldest !== undefined) {
                    sessionControllers.delete(oldest);
                    sessionStores.delete(oldest);
                }
            }
        }
        if (store === undefined) {
            store = controller.bind();
            sessionStores.set(sessionId, store);
        }
        return { controller, store };
    };
    const sessionSwitchesInjected = (sessionId) => {
        const { controller, store } = sessionSwitchesFor(sessionId);
        return {
            hooks: { sessionSwitches: store },
            toggle: (field) => { void controller.toggle(field); },
            clear: () => { void controller.clear(); },
            brandLocale,
        };
    };
    ctx.slots.inject('conversation.input.left', () => ctx.slots.register({
        name: 'conversation.input.left',
        id: 'mbsf-floating-panel',
        order: 100,
        locale: NS,
        inject: sessionSwitchesInjected,
    }, MbsfFloatingPanel));
    return async () => { await unmount(); };
}
